local E = require "ejoysdk_lua.ejoysdk"
local Path = {}

Path.sep = E.File.sep
--[[
根据不同平台的sep, 将base_path和多个path部分join到一起
--]]
Path.join = function(base_path, ...)
    local path_parts = {...}
    local parts_cnt = #path_parts
    if parts_cnt == 0 then
        return base_path
    end

    base_path = Path.trim_end_separator(base_path)
    local all_parts = {base_path}
    local end_part_has_sep_suffix = false
    local cur_idx = 1
    for i=1, parts_cnt, 1 do
        cur_idx = cur_idx + i
        local p = path_parts[i]
        if i == parts_cnt then
            -- current is last part
            local part_len = #p
            local last_ch = p:sub(part_len, part_len)
            end_part_has_sep_suffix = last_ch == '/' or last_ch == '\\'
        end

        p = Path.trim_separators(p)
        all_parts[cur_idx] = p
    end

    local complete_path = table.concat(all_parts, Path.sep)
    -- restore path last seperator
    if end_part_has_sep_suffix then
        complete_path = complete_path .. Path.sep
    end

    return complete_path
end

Path.uniform_sep = function(path)
    path = string.gsub(path, '/', Path.sep)
    return path
end

Path.trim_end_separator = function(path)
    if path == nil or path == '' then
        return path
    end

    local pattern = "^(.-)[/\\]*$"
    return path:gsub(pattern, "%1")
end

Path.trim_separators = function(path)
    if path == nil or path == '' then
        return path
    end

    local pattern = "^[/\\]*(.-)[/\\]*$"
    return path:gsub(pattern, "%1")
end

Path.trim_begin_separator = function(path)
    if path == nil or path == '' then
        return path
    end

    local pattern = "^[/\\]*(.-)$"
    return path:gsub(pattern, "%1")
end

Path.get_ext_file_dir = function()
    return E.File.get_ext_file_dir()
end

local string_by_deleting_last_component = function(path)
    local temp = string.reverse(path)
    -- 考虑2种文件分隔符
    local _, i = string.find(temp,"[/|\\]")
    if i ~= nil then
        local path_len = string.len(path)
        local offset = path_len - i + 1 -- 指向字符串顺序方向的最后一个分隔符的位置
        -- 如果分隔符位于首字符，则统一父目录为空
        if offset == 1 then
            return "", path
        else
            return string.sub(path,1, offset), string.sub(path,offset+1, path_len)
        end
    else
        return "", path
    end
end

--[[
返回路径的父目录(支持windows和linux两种文件分隔符)，有以下两个场景：
1. 文件路径：/aaa/b.txt，则父目录为/aaa/
2. 目录路径：/aaa/bbb/ 则父目录为/aaa/
3. 无父目录场景：/aaa 则父目录为空串
@return 父目录，路径最后一级的名称（可能是文件或者目录名）
--]]
Path.parent_dir = function(path)
    if not path or path == '' then
        return path
    end

    local end_ch = string.sub(path, string.len(path))
    if end_ch == "/" or end_ch == "\\" then
        path = string.sub(path,1, string.len(path)-1)
    end

    local parent_path, last_component = string_by_deleting_last_component(path)
    return parent_path, last_component
end

Path.ensure_parent_dir = function(path)
    -- check dest parent dir exists
    local dest_parent_dir = Path.parent_dir(path)
    local result, _msg

    local parent_dir_exists = false
    if E.is_support_function(E.NATIVE_SUPPORT_FUNCTION_NAMES.FILE_DIR_OPERATION) then
        parent_dir_exists = E.File.exists_fullpath(dest_parent_dir)
    end

    -- 创建目录
    result = parent_dir_exists
    if not parent_dir_exists and E.is_support_function(E.NATIVE_SUPPORT_FUNCTION_NAMES.MAKE_DIRS) then
        result = E.File.make_dirs(dest_parent_dir)
    end

    return result
end

return Path